327: // addOptions adds the parameters in opts as URL query parameters to s. opts
328: // must be a struct whose fields may contain "url" tags.
329: func addOptions[P structPtr[T], T any](s string, opts P) (string, error) {
330: 	if opts == nil {
331: 		return s, nil
332: 	}
333: 
334: 	u, err := url.Parse(s)
335: 	if err != nil {
336: 		return s, err
337: 	}
338: 
339: 	qs, err := query.Values(opts)
340: 	if err != nil {
341: 		return s, err
342: 	}
343: 
344: 	u.RawQuery = qs.Encode()
345: 	return u.String(), nil
346: }
