369: // ClientOptionsFunc is a functional option for providing configuration options
370: // to a Client.
371: type ClientOptionsFunc func(*clientOptions) error
372: 
373: // WithHTTPClient returns a ClientOptionsFunc that sets the http.Client
374: // for a Client. If not set, a default http.Client will be used.
375: func WithHTTPClient(httpClient *http.Client) ClientOptionsFunc {
376: 	return func(o *clientOptions) error {
377: 		if httpClient == nil {
378: 			return errors.New("http client must not be nil")
379: 		}
380: 
381: 		httpClient := *httpClient
382: 		o.httpClient = &httpClient
383: 		return nil
384: 	}
